INSERT INTO research_companies (name, code, industry, seg, listed, round, cap, valuation, rev, last_funding, data, updated_at) VALUES
('蝴蝶效应（Manus）', '—', 'ai', 'ai-agent', false, '回购后新一轮（进行中）', NULL, 280, NULL, '2026-08',
'{"name":"蝴蝶效应（Manus）","code":"—","industry":"ai","seg":"ai-agent","listed":false,"desc":"全球首款通用智能体产品，ARR 从 1 亿美元增至 4-5 亿美元，腾讯牵头以 20 亿美元从 Meta 回购，正推进 40 亿美元估值新融资并转道中国香港上市。","valuation":280,"round":"回购后新一轮（进行中）","lastFunding":"2026-08","latestFunding":"2026-08 · 腾讯牵头回购 20 亿美元；新一轮拟融 5 亿美元、投后估值目标 40 亿美元","execChanges":[],"latestTech":"通用 Agent 自主执行能力（浏览器操作、表单填写、数据提取、研究报告生成），跨平台多步任务编排","detail":"【定位说明】Manus 是中国 AI 智能体赛道估值最高的初创公司（母公司蝴蝶效应 Butterfly Effect，2022 年成立，总部新加坡），2025 年因邀请码被炒至 10 万元成为全球 AI Agent 的**现象级标杆产品**。收录入「通用 Agent」环节，是这一赛道唯一具备国际影响力与规模化收入的中国创业公司样本。\n【产品与起源】团队最初做 AI 浏览器插件 Monica，后转向自主智能体。Manus 能自主筛选简历、分析股票、生成研究报告，把 AI Agent 从概念推向可用性产品。2025 年 3 月发布后病毒式传播，4 月获 Benchmark 领投 7500 万美元融资，6 月将全球总部迁至新加坡。\n【资本的三次转折——本案例最值得记录的部分】① 2025 年 12 月 30 日，Meta 宣布以**超 20 亿美元**收购蝴蝶效应，为其成立以来规模第三大并购案（较此前 1 亿美元估值账面回报超 23 倍，PS 约 20 倍）；② 2026 年 4 月 27 日，国家发改委外商投资安全审查工作机制办公室依据《外商投资安全审查办法》作出**禁止投资决定、要求撤销交易**——这是该办法 2021 年实施以来首个被公开叫停的 AI 领域外资收购案，也是该框架下最严厉的档位；③ 2026 年 7 月，腾讯牵头真格基金、红杉中国等中方资本按 **20 亿美元（与 Meta 收购价持平）**回购全部股权，8 月底获批并签署。腾讯成为最大外部股东但**不控股**，实控方仍为创始团队，红杉中国与真格基金各持约 10%，Benchmark 退出。消息公布当日腾讯港股下跌 2.21%。\n【ARR 的火箭式增长与关键疑点】被收购时（2025 年 12 月）ARR 约 1 亿美元；截至 2026 年 6 月底已攀升至 **4-5 亿美元**，不到一年增长 4-5 倍，日收入从约 30 万美元涨至近 150 万美元。**但这轮增长的归因必须打问号**：Meta 完成收购后不到两个月就把 Manus 嵌入 Ads Manager（向超 1000 万广告主开放），随后推入 WhatsApp Business 与 Instagram 生态——增长最快的七个月中，作为「Meta 一部分」运营的阶段占据相当部分，这部分由 Meta 渠道灌入的收入在脱离生态后能否延续、续费率能否维持，存在实质不确定性。\n【成本结构与独立运营的考题】据凤凰网财经报道，Manus 顶峰期日均算力成本约 50 万美元、月均约 1500 万美元，而 ARR 1 亿美元对应月均收入仅约 833 万美元；叠加 Anthropic API 账单每月吃掉近一半收入，**毛利率与算力自给能力是最大隐患**。按 4 月监管决定，Meta 须删除所有 Manus 境内用户数据、终止技术授权、恢复数据本地化存储——Manus 需重建获客渠道、企业客户与技术基础设施；且被 Meta 收购时其国内基础已清零（清空社交媒体、屏蔽中国 IP、停止国内服务）。\n【估值与 IPO】腾讯方相当于以原价买回 4-5 倍收入体量，按 20 亿美元对价计 PS 仅 4-5 倍（同行 Anthropic 约 20 倍 ARR、智谱约 4-5 倍），账面上是「折扣价」。2026 年 9 月彭博社报道，Manus 正推进约 5 亿美元新融资，**投后估值目标 40 亿美元**（较 Meta 收购价翻倍），IDG 资本、博裕资本为潜在投资方，腾讯、红杉中国、真格基金有意跟投；若落地将成为中国估值最高的 AI 智能体初创公司。公司继续在新加坡独立运营，该结构为未来**中国香港 IPO** 保留选择权。\n【观察指标】脱离 Meta 渠道后的 ARR 留存率与续费率、算力成本占收入比重能否下降、新一轮 40 亿美元估值融资的实际落地情况、中国香港上市进程。","tech":[],"funding":[{"date":"2023-02","round":"种子轮","inv":"真格基金"},{"date":"2023-08","round":"天使轮","inv":"真格基金"},{"date":"2024-11","round":"A轮","inv":"红杉中国、腾讯、真格基金、王慧文、Old Friendship Capital"},{"date":"2025-04","round":"B轮","inv":"Benchmark Capital、真格基金、红杉中国、腾讯等中美头部VC及科技公司创业者"},{"date":"2025-10","round":"收购","inv":"Meta（扎克伯格）以数十亿美元收购"}],"investorsStructured":[{"name":"Benchmark Capital","role":"lead","round":"B轮","date":"2025-04","kind":"vc"},{"name":"真格基金","role":"lead","round":"种子轮","date":"2023-02","kind":"vc","note":"多轮跟投"},{"name":"Meta","role":"strategic","round":"收购","date":"2025-10","kind":"cvc","note":"Meta史上第三大并购，仅次于WhatsApp和Scale AI"},{"name":"Old Friendship Capital","role":"follow","round":"A轮","date":"2024-11","kind":"vc"},{"name":"王慧文","role":"follow","round":"A轮","date":"2024-11","kind":"other"},{"name":"红杉中国","role":"follow","round":"A轮","date":"2024-11","kind":"vc"},{"name":"腾讯","role":"follow","round":"A轮","date":"2024-11","kind":"cvc"}]}'::jsonb, now())
