'{"name":"息壤开物","code":"—","industry":"ai","seg":"llm","listed":false,"desc":"原生物理基础模型（LPM），由前华为云大模型 CTO 李寅与华为多模态首席科学家张含望创办","valuation":35,"round":"种子轮 + 天使轮","lastFunding":"2026年9月23日","latestFunding":"2026年9月23日 · 种子轮 + 天使轮（累计数亿元，投后估值 5 亿美元）","execChanges":[],"latestTech":"WorldArena 2.0 全球总决赛 Track 1 视频质量赛道轨迹精度全球第一、物理合规性全球前三","tech":[{"date":"2026年9月16日","kind":"技术突破","title":"WorldArena 2.0 全球总决赛 Track 1 轨迹精度全球第一、物理合规性全球前三"}],"funding":[{"date":"2026年9月23日","round":"种子轮 + 天使轮","amount":"数亿元","inv":"敦鸿资产领投，华控基金 / 三花控股 / 银杏谷资本 / 泽然资本 / 本坚基金 / 上海天使会 / 标朴投资跟投"},{"date":"2026","round":"种子轮及天使轮","amount":"数亿元（连续完成）","inv":"敦鸿资产领投，华控基金、三花控股、银杏谷资本、泽然资本、本坚基金、天使基石（上海天使会）、标朴投资等跟投"}],"investorsStructured":[{"name":"敦鸿资产","role":"lead","round":"种子轮及天使轮","date":"2026","kind":"vc"},{"name":"三花控股","role":"follow","round":"种子轮及天使轮","date":"2026","kind":"cvc"},{"name":"华控基金","role":"follow","round":"种子轮及天使轮","date":"2026","kind":"vc"},{"name":"标朴投资","role":"follow","round":"种子轮及天使轮","date":"2026","kind":"vc"},{"name":"泽然资本","role":"follow","round":"种子轮及天使轮","date":"2026","kind":"vc"},{"name":"银杏谷资本","role":"follow","round":"种子轮及天使轮","date":"2026","kind":"vc"}]}'::jsonb, now())
