INSERT INTO research_companies (name, code, industry, seg, listed, round, cap, valuation, rev, last_funding, data, updated_at) VALUES
('三启万物（VAST）', '—', 'ai', 'llm', false, 'B+ 轮', NULL, 71, NULL, '2026年9月',
'{"name":"三启万物（VAST）","code":"—","industry":"ai","seg":"llm","listed":false,"desc":"全球 AI 3D 模型生成量第一，Tripo 系列 3D 原生基座模型 + 世界模型 Project Eden，估值 10 亿美元，传赴港 IPO。","valuation":71,"round":"B+ 轮","lastFunding":"2026年9月","latestFunding":"2026年9月 · B 轮及 B+ 轮合计约 30 亿元；年内累计融资约 50 亿元，刷新 3D 原生智能领域融资额纪录","execChanges":[],"latestTech":"Tripo P2.0（2026-08）为全球首个支持原生四边面拓扑网格的 3D 原生基座模型，同时满足「引擎可用、动画可绑、编辑可及」三个工业级门槛；Project Eden 为全球首个允许对世界状态进行自主维护与确定性控制的世界模型","detail":"【定位说明】VAST（三启万物）成立于 2023 年 3 月，创始人宋亚宸为前 MiniMax 联合创始成员（97 后，约翰霍普金斯大学毕业，曾任职商汤 CEO 徐立助理），聚焦 **3D 原生基础模型与世界模型**研发。收录入「基础大模型 → 多模态大模型」环节——其能力已从单一 3D 生成延伸到物理世界建模，是本环节「向物理基础模型延伸」这一趋势最直接的样本。\n【技术体系：两条主线】① **3D 原生基座模型 Tripo 系列**——H 系列侧重几何细节（Tripo H3.1 可生成雕塑级几何细节），P 系列侧重生产效率（Tripo P1.0 为全球唯一秒级输出生产级网格的 3D 大模型，较同类方案提速百倍，首次实现 3D 资产生成即入工业管线）；2026 年 8 月发布的 **Tripo P2.0 基于自研 Nexus 生成框架，实现原生四边面拓扑网格生成**，是全球首个支持该拓扑的 3D 原生基座模型，让生成资产能直接进入游戏引擎、可绑定动画、可继续编辑——这是从「生成可展示的模型」到「生成可继续使用的资产」的关键跃迁。② **世界模型 Project Eden**（2026 年 5 月公布）——采用三层解耦式架构，将底层状态推演与视觉渲染原生解耦，成为**全球首个允许对世界状态进行自主维护与确定性控制的世界模型**，自然解锁环境长程持久、场景自由复用、多人并发交互等能力，定位为下一代互动内容引擎与具身智能仿真基座。\n【商业化与用户规模】产品矩阵为「自研 3D 基础模型及世界模型 + 一站式原生工作台 Tripo Studio + 生态应用」端到端闭环，Tripo Studio 覆盖概念生成、建模、贴图、分割、拓扑、绑定、动画到导出全流程。截至 2026 年 7 月：**全球注册用户突破 2000 万，服务超 650 万创作者和 4 万家企业客户，累计生成 3D 模型近 1 亿个，全球 AI 3D 模型生成数量排名第一**。落地场景已进入真实生产工作流——游戏（网易《蛋仔派对》蛋仔工坊 3D 模型拆分、《燕云十六声》上传照片实时生成可交互 3D 虚拟形象）、3D 打印（最早接入拓竹科技 MakerWorld，并与多家 3D 打印软硬件企业合作）、影视动画（海外创意平台 Intangible AI 及国内领先视频平台接入）、空间设计（与群核科技酷家乐战略合作，数秒生成高精度 3D 模型）、XR 与智能制造。生态合作覆盖阿里巴巴、腾讯、字节、网易、优必选等，客户含索尼、微软，**被视为海外渗透率最高的国产 AI 公司之一**。\n【融资：年内累计约 50 亿元，刷新赛道纪录】2026 年是融资最密集的一年——6 月完成 A+ 及 A++ 两轮合计近 2 亿美元（渶策资本、国寿长三角科创基金领投，深圳市人工智能终端产业基金（产业方荣耀）、深创投、元生资本等联合投资，春华创投、靖亚资本、BV 百度风投等老股东追投）；7 月完成超 10 亿元 A3 战略轮（吉利资本等产业方，四三九九、贪玩游戏、巨人网络等游戏厂商，亦庄国投、基石资本等参投）；**9 月完成 B 轮及 B+ 轮合计约 30 亿元，由经纬创投领投**，完美世界、蓝色光标、芯动能投资、延趣游戏、中科创达、广电投资、三七互娱等产业资本，鼎晖 VGC、中金资本、CMC 资本、洪泰基金、三正健康投资、中平资本、福建产投基金、福创投、卓源亚洲、江西金控等联合参投，老股东达晨财智、春华资本、四三九九、慕华科创、绿洲资本、渶策资本、华控基金等追投。不到半年累计融资约 50 亿元，**刷新 3D 原生智能领域融资额纪录**，估值达 10 亿美元。\n【IPO 预期】2026 年 8 月彭博社援引知情人士称，VAST 正考虑**中国香港 IPO**，正与美国银行和中金公司就潜在股票发行计划合作；相关讨论仍在进行、尚未作出最终决定，三方均拒绝置评。\n【风险】①**世界模型是长周期技术竞赛，国内竞争格局尚处发展初期**，Project Eden 目前仍属研究项目，与 Tripo 的商业化体量之间存在明显时间差；②AI 3D 生成的需求分散在游戏、3D 打印、影视、XR 等长尾场景，单场景付费深度有限，规模化订阅模式的成立性有待验证；③赛道竞争快速升温，需警惕大厂以通用多模态模型降维切入 3D 生成；④公司尚未披露收入与利润数据，10 亿美元估值完全建立在用户规模与技术领先性之上，估值锚不稳；⑤创始团队出自 MiniMax、商汤，技术背景强但公司成立仅三年，组织与治理仍在成型期。\n【观察指标】Tripo Studio 付费转化率与 ARPU、企业客户数（4 万家）的增长斜率、Project Eden 从研究项目到产品化的时点、中国香港 IPO 进程。","tech":[{"date":"2026年8月","kind":"产品动态","title":"Tripo P2.0 发布，全球首个支持原生四边面拓扑网格的 3D 原生基座模型"},{"date":"2026年5月","kind":"技术突破","title":"世界模型 Project Eden 公布，全球首个可对世界状态自主维护与确定性控制的模型"},{"date":"2026年3月","kind":"产品动态","title":"Tripo H3.1 与 P1.0 双模型发布，P1.0 为全球唯一秒级输出生产级网格的 3D 大模型"}],"funding":[{"date":"2026年9月","round":"B 轮 / B+ 轮","amount":"合计约 30 亿元","inv":"经纬创投领投 / 完美世界 / 蓝色光标 / 芯动能投资 / 延趣游戏 / 中科创达 / 广电投资 / 三七互娱 / 鼎晖 VGC / 中金资本 / CMC 资本 / 洪泰基金 / 三正健康投资 / 中平资本 / 福建产投基金 / 福创投 / 卓源亚洲 / 江西金控等"},{"date":"2026年7月","round":"A3 战略轮","amount":"超 10 亿元","inv":"吉利资本 / 四三九九 / 贪玩游戏 / 巨人网络 / 亦庄国投 / 基石资本等"},{"date":"2026年6月","round":"A+ / A++ 轮","amount":"合计近 2 亿美元","inv":"渶策资本 / 国寿长三角科创基金领投；深圳市人工智能终端产业基金（荣耀）/ 深创投 / 元生资本等；春华创投 / 靖亚资本 / BV 百度风投追投"},{"date":"2026-09","round":"B轮及B+轮","amount":"合计约30亿元","inv":"经纬创投领投，完美世界、蓝色光标、芯动能投资、延趣游戏、中科创达、广电投资、三七互娱等产业资本；鼎晖VGC、中金资本、CMC资本、洪泰基金、福建产投基金、福创投、卓源亚洲、江西金控等联合参投；老股东达晨财智、春华资本、四三九九、慕华科创、绿洲资本、渶策资本、华控基金追投"},{"date":"2026-07","round":"A3轮","amount":"超10亿元","inv":"四三九九、贪玩游戏、巨人网络等游戏厂商"},{"date":"2026-03","round":"A轮","amount":"5000万美元","inv":"阿里巴巴、恒旭资本等联合投资"},{"date":"2026","round":"A+轮及A++轮","amount":"近2亿美元","inv":"未完整披露"},{"date":"2025","round":"Pre-A+轮","inv":"北京市人工智能产业投资基金、靖亚资本"},{"date":"2024","round":"Pre-A轮","inv":"达晨财智、春华资本等"}],"investorsStructured":[{"name":"北京市人工智能产业投资基金","role":"lead","round":"Pre-A+轮","date":"2025","kind":"gov"},{"name":"经纬创投","role":"lead","round":"B轮及B+轮","date":"2026-09","kind":"vc"},{"name":"达晨财智","role":"lead","round":"Pre-A轮","date":"2024","kind":"vc"},{"name":"阿里巴巴","role":"lead","round":"A轮","date":"2026-03","kind":"cvc"},{"name":"CMC资本","role":"follow","round":"B轮及B+轮","date":"2026-09","kind":"pe"},{"name":"三七互娱","role":"follow","round":"B轮及B+轮","date":"2026-09","kind":"cvc"},{"name":"中科创达","role":"follow","round":"B轮及B+轮","date":"2026-09","kind":"cvc"},{"name":"中金资本","role":"follow","round":"B轮及B+轮","date":"2026-09","kind":"pe"},{"name":"完美世界","role":"follow","round":"B轮及B+轮","date":"2026-09","kind":"cvc"},{"name":"恒旭资本","role":"follow","round":"A轮","date":"2026-03","kind":"cvc"},{"name":"春华资本","role":"follow","round":"Pre-A轮","date":"2024","kind":"pe"},{"name":"江西金控","role":"follow","round":"B轮及B+轮","date":"2026-09","kind":"gov"},{"name":"洪泰基金","role":"follow","round":"B轮及B+轮","date":"2026-09","kind":"vc"},{"name":"蓝色光标","role":"follow","round":"B轮及B+轮","date":"2026-09","kind":"cvc"},{"name":"靖亚资本","role":"follow","round":"Pre-A+轮","date":"2025","kind":"vc"},{"name":"鼎晖VGC","role":"follow","round":"B轮及B+轮","date":"2026-09","kind":"vc"}]}'::jsonb, now())
