轮","date":"2024-08","kind":"vc"},{"name":"海富产业基金","role":"follow","round":"C轮","date":"2018-11","kind":"gov"},{"name":"申万宏源证券","role":"follow","round":"C+轮","date":"2020-12","kind":"pe"},{"name":"百世集团","role":"follow","round":"A轮","date":"2015-10","kind":"cvc"},{"name":"软银中国","role":"follow","round":"B轮","date":"2017-03","kind":"vc"},{"name":"远雄集团（Farglory）","role":"follow","round":"D轮","date":"2024-09","kind":"cvc"},{"name":"Prosperity7 Ventures","role":"other","round":"C+轮","date":"2020-12","kind":"cvc"},{"name":"中兴合创","role":"other","round":"A轮","date":"2015-10","kind":"cvc"},{"name":"中赢资产","role":"other","round":"股权转让","date":"2025-05","kind":"other"},{"name":"临港科创投","role":"other","round":"Pre-D轮","date":"2022-08","kind":"gov"},{"name":"交银国际","role":"other","round":"C+轮","date":"2020-12","kind":"pe"},{"name":"凯傲集团","role":"other","round":"C+轮","date":"2020-12","kind":"cvc"},{"name":"创世伙伴CCV","role":"other","round":"C+轮","date":"2020-12","kind":"vc"},{"name":"博华资本","role":"other","round":"D+轮","date":"2024-08","kind":"pe"},{"name":"建信（北京）投资","role":"other","round":"C+轮","date":"2020-12","kind":"pe"},{"name":"林德叉车","role":"other","round":"C+轮","date":"2020-12","kind":"cvc"},{"name":"梁溪科创母基金","role":"other","round":"D轮","date":"2024-09","kind":"gov"},{"name":"洪泰基金","role":"other","round":"D+轮","date":"2024-08","kind":"vc"},{"name":"海富产业基金","role":"other","round":"C轮","date":"2018-11","kind":"gov"},{"name":"申万宏源证券","role":"other","round":"C+轮","date":"2020-12","kind":"pe"},{"name":"百世物流","role":"other","round":"A轮","date":"2015-10","kind":"cvc"},{"name":"联创永宣","role":"other","round":"C轮","date":"2018-11","kind":"vc"},{"name":"远雄集团","role":"other","round":"D轮","date":"2024-09","kind":"other"},{"name":"金杜鹃资本","role":"other","round":"D轮","date":"2024-09","kind":"vc"}]}'::jsonb, now())
