INSERT INTO research_companies (name, code, industry, seg, listed, round, cap, valuation, rev, last_funding, data, updated_at) VALUES
('思敏威', NULL, 'semiconductor', 'design', false, '天使轮', NULL, NULL, NULL, '2026-10',
'{"name":"思敏威","industry":"semiconductor","seg":"design","listed":false,"round":"天使轮","valuation":null,"lastFunding":"2026-10","desc":"思敏威（上海）集成电路有限公司（CiMicro.Ai），2024 年 12 月成立于上海浦东张江，3D 存算一体 AI 推理芯片设计公司。采用「3D 堆叠近存计算 + SRAM 存内计算 + 自研 RISC-V 计算核心 + Chiplet 芯粒互联」融合架构，核心产品为青衡 3D-HPU（存算融合架构）与 3D-cHMC（3D-computing Hyper Memory Cube，3D 算力超存立方）基座，面向大模型推理与端侧 AI 场景，目标把推理能效提升一个数量级。创始团队来自英特尔、AMD、华为海思，核心成员平均 20 年以上 SoC 设计经验、10 年以上存算一体积累，累计流片 20 余次；2025 年率先完成 FP4 浮点存内计算核心 IP 验证，近五年在 ISSCC / JSSC 发表论文 11 篇。","latestTech":"2026 年推进青衡 3D-HPU 系列产品化，与领开半导体达成 3D 堆叠存算融合 + HBF+ 战略合作，切入高带宽存储近存计算路线","tech":[{"date":"2026-06","title":"与领开半导体（东方富海系）达成战略合作，围绕 3D 堆叠存算融合架构与 HBF+（高带宽闪存）技术路线共同开发"},{"date":"2026","title":"与无问芯穹建立商业合作，存算一体推理方案接入其异构算力与推理引擎生态"},{"date":"2025","title":"率先完成 FP4 浮点存内计算核心 IP 验证，成为国内少数打通低精度浮点存内计算链路的团队"},{"date":"2024-12","title":"公司于上海浦东张江注册成立，确定 3D 存算一体 AI 推理芯片方向"}],"executives":[{"name":"李明","title":"法定代表人","role":"management","bio":"思敏威（上海）集成电路有限公司法定代表人。公司由具备英特尔、AMD、华为海思背景的 SoC 与存算一体团队创立，核心成员平均拥有 20 年以上芯片设计经验、10 年以上存算一体技术积累，累计完成 20 余次流片，近五年在 ISSCC、JSSC 等集成电路顶级会议与期刊发表论文 11 篇。技术路线覆盖 SRAM 存内计算、3D 异质封装近存计算、RISC-V 计算核心与 Chiplet 芯粒互联，2025 年率先完成 FP4 浮点存内计算核心 IP 验证。"}],"investorsStructured":[{"name":"中兴通讯","role":"strategic","round":"天使轮","date":"2026-10","kind":"cvc","note":"战略投资，通信设备与算力服务器场景协同"},{"name":"博华产投","role":"follow","round":"天使轮","date":"2026-10","kind":"cvc"},{"name":"松青资本","role":"follow","round":"天使轮","date":"2026-10","kind":"vc"},{"name":"建信信托","role":"follow","round":"天使轮","date":"2026-10","kind":"pe"},{"name":"合创资本","role":"follow","round":"天使轮","date":"2026-10","kind":"vc"},{"name":"德同资本","role":"follow","round":"天使轮","date":"2026-10","kind":"vc","note":"老股东追投，同时参与种子轮"},{"name":"东方富海","role":"lead","round":"种子轮","date":"2026-05","kind":"vc","note":"联合领投"},{"name":"纪源资本","role":"lead","round":"种子轮","date":"2026-05","kind":"vc","note":"联合领投"},{"name":"徐汇资本","role":"follow","round":"种子轮","date":"2026-05","kind":"gov","note":"上海徐汇区国资背景"},{"name":"赛智伯乐","role":"follow","round":"种子轮","date":"2026-05","kind":"vc"}],"funding":[{"date":"2026-10","round":"天使轮","amount":"约亿元","inv":"战略投资：中兴通讯；联合投资：博华产投 / 松青资本 / 建信信托 / 合创资本；老股东追投：德同资本","investors":"中兴通讯（战略投资）· 博华产投 · 松青资本 · 建信信托 · 合创资本 · 德同资本（老股东追投）"},{"date":"2026-05","round":"种子轮","amount":"近亿元","inv":"领投：东方富海 / 纪源资本；跟投：徐汇资本 / 德同资本 / 赛智伯乐","investors":"东方富海（领投）· 纪源资本（领投）· 徐汇资本 · 德同资本 · 赛智伯乐"}],"note":"存算一体 AI 推理芯片国产替代对标：存算一体路线在能效上对标 Mythic（美国，模拟存内计算）、Syntiant（美国，端侧低功耗 NDP）、d-Matrix（美国，数字存内计算 + 3D 近存，主打数据中心推理）、Axelera AI（荷兰，数字 CIM）等国际厂商。思敏威是国内少数同时布局「3D 堆叠近存计算」与「SRAM 存内计算」双路线、并打通 FP4 浮点存内计算 IP 的团队，差异化在于以大模型推理为目标场景，用 3D 异质集成突破 SRAM-CIM 容量瓶颈。产业协同上已接入中兴通讯（战略股东，通信设备与算力服务器场景）与无问芯穹（推理引擎生态），并与领开半导体共同推进 HBF+ 高带宽闪存路线。风险在于存算一体的模拟精度一致性、编译器与工具链生态仍不成熟，且国内 CIM 赛道 C 轮之后融资断层，产业化节奏依赖大客户验证与流片窗口。"}'::jsonb, now())
ON CONFLICT (name) DO UPDATE SET code=EXCLUDED.code, industry=EXCLUDED.industry, seg=EXCLUDED.seg, listed=EXCLUDED.listed, round=EXCLUDED.round, cap=EXCLUDED.cap, valuation=EXCLUDED.valuation, rev=EXCLUDED.rev, last_funding=EXCLUDED.last_funding, data=EXCLUDED.data, updated_at=now();

INSERT INTO research_companies (name, code, industry, seg, listed, round, cap, valuation, rev, last_funding, data, updated_at) VALUES
('睿龙科技', '874818.NQ', 'semiconductor', 'material', false, '新三板挂牌', NULL, NULL, NULL, NULL,
'{"name":"睿龙科技","code":"874818.NQ","industry":"semiconductor","seg":"material","listed":false,"round":"新三板挂牌","market":"CN","desc":"睿龙材料科技无锡股份有限公司，2016 年成立于江苏无锡，2025 年 7 月在新三板创新层挂牌（874818），是国家级专精特新「小巨人」企业。公司专注高端覆铜板（CCL）及半固化片（PP）的研发、制造与销售，定位于「先进互联解决方案服务商」，产品矩阵覆盖 PTFE/碳氢高频材料、BT 封装基板材料、PPO 高速材料、环氧中高 Tg 材料四大体系。技术团队具备 20 年以上行业经验，配备国际先进的研发、生产及检测设备。产品既应用于计算机、通信、医疗、汽车电子及工业控制等高端民用领域，也深度参与卫星通信、相控阵雷达、航空防撞系统及联合战术无线电系统等国防航天项目，是多项国家级重大工程及 5G 基站建设的重要基础材料供应商。2025 年营收 3.01 亿元（+37.53%），净利润 1.437 亿元（+30.80%），扣非净利润 1.420 亿元（+36.83%）。公司已于 2025 年 7 月通过北交所「绿色通道 + 直联审核」机制同步申报挂牌与上市，为全国首批采用该机制的企业之一，2024 年 1 月与国泰海通签署上市辅导协议，至 2026 年 5 月累计开展 9 期辅导，目前处于辅导验收阶段。","tech":[{"date":"2026-06","title":"关于北交所发行上市计划不确定性的风险提示公告（六）","kind":"公告","desc":"公司披露：2025 年营业收入和归属于挂牌公司股东的净利润分别为 30082.17 万元和 14370.86 万元；2025 年上半年营收 22099.30 万元、净利 12458.65 万元，下半年财务指标环比有所下滑，提醒投资者关注业绩波动可能导致的上市失败风险。"},{"date":"2026-04","title":"拟公开发行不超过 4000 万股并在北交所上市","kind":"融资","desc":"公司董事会审议通过申请向不特定合格投资者公开发行股票并在北交所上市，拟发行不超过 4000 万股（未考虑超额配售），可择机采用不超过本次发行数量 15%（即 600 万股）的超额配售选择权，募集资金投向「新一代高端电路材料产业化建设项目」。"},{"date":"2025-07","title":"入选北交所「绿色通道 + 直联审核」首批企业","kind":"资质","desc":"公司通过北交所「绿色通道 + 直联审核」机制同步申报挂牌与上市，成为全国首批采用该创新审核机制的企业之一，并于 2025 年 7 月进入新三板创新层。"},{"date":"2025","title":"BT 封装基板材料 + PPO 高速材料双线突破","kind":"产品","desc":"公司高端材料体系覆盖 PTFE/碳氢高频材料、BT 封装基板材料、PPO 高速材料、环氧中高 Tg 材料，直接对应 IC 载板基材与 AI 算力高速板的国产替代需求。"},{"date":"2025","title":"业绩同比增长 37.53%，净利 1.44 亿元","kind":"业绩","desc":"2025 年公司实现营业收入 3.008 亿元，同比增长 37.53%；净利润 1.437 亿元，同比增长 30.80%。业绩增长主要系大力开拓市场、下游客户订单需求增加，同时优化管理体系、深化精益管理提升整体经营效率。"}],"funding":[{"date":"2025","round":"战略投资","inv":"高信资本"}],"investorsStructured":[{"name":"高信资本","role":"lead","round":"战略投资","date":"2025","kind":"vc","note":"布局高频高速覆铜板赛道"}],"note":"并购标的视角：睿龙科技是本次筛选中「利润质地最优 + 赛道最对口」的组合——2025 年净利 1.437 亿元（扣非 1.420 亿元）远超 5000 万门槛，且利润几乎全部来自经营性损益，无政府补助或资产处置依赖；产品体系中的 BT 封装基板材料与 PPO 高速材料正是 IC 载板与 AI 算力高速板的核心基材，与深主板 PCB/载板企业的纵向整合逻辑最直接。核心障碍在于时间窗：公司已于 2025 年 7 月通过北交所「绿色通道 + 直联审核」同步申报挂牌与上市，目前处于辅导验收阶段，2026 年 6 月已发布第六次上市计划不确定性风险提示，需尽快接触以抢在发行定价之前。此外需注意公司 2025 年下半年业绩环比下滑（上半年净利 1.246 亿元，全年 1.437 亿元），主因下半年客户订单放缓，业绩稳定性需持续跟踪；国防军工客户占比不低，股权与业务受让或涉及特殊资质审查。"}'::jsonb, now())
ON CONFLICT (name) DO UPDATE SET code=EXCLUDED.code, industry=EXCLUDED.industry, seg=EXCLUDED.seg, listed=EXCLUDED.listed, round=EXCLUDED.round, cap=EXCLUDED.cap, valuation=EXCLUDED.valuation, rev=EXCLUDED.rev, last_funding=EXCLUDED.last_funding, data=EXCLUDED.data, updated_at=now();

INSERT INTO research_companies (name, code, industry, seg, listed, round, cap, valuation, rev, last_funding, data, updated_at) VALUES
('株洲科能', NULL, 'semiconductor', 'material', false, '科创板 IPO 已受理', NULL, NULL, NULL, NULL,
'{"name":"株洲科能","industry":"semiconductor","seg":"material","listed":false,"round":"科创板 IPO 已受理","market":"CN","desc":"株洲科能新材料股份有限公司，2001 年 1 月成立于湖南株洲，注册资本未公开，是国家级专精特新企业。公司主营研发、生产化合物半导体以及 ITO、IGZO 等靶材合成所需的核心关键基础材料，处于高纯稀散金属材料领域，收入高度集中于铟、镓、铋三大系列产品（报告期各期合计占主营业务收入 95.47%、96.57%、97.49%）。公司精铟产品国内市场占有率 2023 年、2024 年位居第一，2025 年位居第三。2023—2025 年营业收入分别为 6.09 亿元、7.87 亿元、10.27 亿元，归母净利润分别为 3946.53 万元、7074.19 万元、1.28 亿元（同比 +80.3%），扣非后归母净利润分别为 0.39 亿元、0.71 亿元、1.22 亿元。国际竞争对手包括 Dowa、Rasa、Indium Corporation、5N Plus、广东先导、北京通美。公司曾于 2023 年 6 月申报科创板 IPO，2025 年 10 月 31 日撤回；2026 年 5 月 11 日二度申报科创板获上交所受理，保荐机构为申港证券，本次拟募资 5.6 亿元投向「年产 500 吨半导体高纯材料项目及回收项目」「稀散金属先进材料研发中心建设项目」及补充流动资金。","tech":[{"date":"2026-05","title":"科创板 IPO 二度获受理，拟募资 5.6 亿元","kind":"融资","desc":"5 月 11 日上交所官网披露公司科创板 IPO 获受理，保荐机构为申港证券，保荐代表人叶华、佘飞飞。距 2025 年 10 月 31 日前次撤回仅间隔 6 个月，为第二次冲刺科创板。募资投向年产 500 吨半导体高纯材料项目及回收项目、稀散金属先进材料研发中心建设项目及补充流动资金。"},{"date":"2026-01","title":"赵科湘转任总工程师，核心技术人员职责明确","kind":"人事","desc":"2026 年 1 月起，赵科湘（董事长赵科峰之弟）由董事兼副总经理转任公司总工程师，同时任能晖新材总经理。其为大专学历、高级工程师，长沙理工大学与湖南科技大学材料科学与工程学院客座教授。"},{"date":"2025","title":"精铟产品国内市占率 2023/2024 第一、2025 第三","kind":"市场","desc":"公司多项铟产品市占率居前，精铟产品国内市场占有率在 2023 年和 2024 年位居第一，2025 年位居第三。"},{"date":"2025","title":"营收突破 10 亿元，归母净利同比增长 80.3%","kind":"业绩","desc":"2025 年公司实现营业收入 10.27 亿元，同比增长 30.50%；归母净利润 1.28 亿元，同比增长 80.3%；扣非后归母净利润 1.22 亿元。收入高度集中于铟、镓、铋三大系列产品。"},{"date":"2025","title":"报告期经营活动现金流量净额持续为负","kind":"风险","desc":"2023—2025 年经营活动产生的现金流量净额分别为 −1.27 亿元、−3.29 亿元、−1.89 亿元，主要系根据订单需求大幅增加原材料采购备货、支付采购款增加所致；投资活动现金流量净额分别为 −0.39 亿元、−0.12 亿元、−0.38 亿元。"},{"date":"2025-10","title":"前次科创板申报撤回","kind":"公告","desc":"2025 年 10 月 31 日，公司撤回 2023 年 6 月申报的科创板 IPO 申请，原保荐机构亦为申港证券，前次申报曾遭监管警示。"}],"executives":[{"name":"赵科峰","title":"董事长兼总经理","role":"management","shares":"直接 23.74%，通过科能先进控制 27.05%，另经株洲凯联控制 6.01%、株洲新联诚控制 1.31%","bio":"男，1972 年 12 月出生，中国国籍，已取得澳大利亚永久居留权，研究生学历。1993 年 7 月至 2001 年 1 月就职于株洲硬质合金集团；2001 年 1 月至 2021 年 7 月就职于科能有限，任执行董事兼总经理；2021 年 7 月至今任公司董事长兼总经理。与唐燕为共同实际控制人。"},{"name":"唐燕","title":"共同实际控制人","role":"board","shares":"直接 2.93%","bio":"女，1975 年 10 月出生，中国国籍，已取得澳大利亚永久居留权。与赵科峰为夫妻关系，二人直接和间接合计控制公司 61.05% 股份。"},{"name":"赵科湘","title":"总工程师","role":"management","shares":"2.78%","bio":"男，1977 年 1 月出生，中国国籍，无境外永久居留权，大专学历，高级工程师，长沙理工大学客座教授、湖南科技大学材料科学与工程学院客座教授。1997 年 9 月至 2010 年 12 月就职于株洲冶炼集团任质保部技术员；2011 年 1 月至 2021 年 7 月任科能有限副总经理；2021 年 7 月至 2024 年 7 月任公司副董事长兼副总经理；2024 年 7 月至 2025 年 12 月任董事兼副总经理；2026 年 1 月至今任总工程师、能晖新材总经理。系董事长赵科峰之弟。"},{"name":"赵晓江","title":"股东（一致行动人）","role":"board","shares":"0.19%","bio":"系赵科峰之妹，与赵科峰、唐燕、赵科湘构成一致行动关系。"}],"investorsStructured":[{"name":"金石基金","role":"other","round":"Pre-IPO","date":"2026","kind":"pe","note":"持股 8.24%，为持股 5% 以上的其他股东"},{"name":"天惠投资基金","role":"other","round":"A 轮","date":"2021-04","kind":"gov","note":"2021 年 4 月 A 轮投资方之一，亦为 5% 以上股东"},{"name":"安芯投资","role":"other","round":"A 轮","date":"2021-04","kind":"pe","note":"安芯投资（安芯众志、安芯众城）为 5% 以上股东"},{"name":"中信金石","role":"other","round":"A 轮","date":"2021-04","kind":"pe"},{"name":"深圳市高上资本","role":"other","round":"A 轮","date":"2021-04","kind":"vc"},{"name":"中金资本","role":"other","round":"A+ 轮","date":"2022-03","kind":"pe"},{"name":"鑫鼎国瑞","role":"other","round":"A+ 轮","date":"2022-03","kind":"pe"},{"name":"博时创新","role":"other","round":"A+ 轮","date":"2022-03","kind":"pe"}],"funding":[{"date":"2026-05","round":"科创板 IPO 受理","amount":"拟募 5.6 亿元","investors":"申港证券保荐（公开发行）","inv":"申港证券保荐（公开发行）"},{"date":"2022-03","round":"A+ 轮","amount":"未披露","investors":"中金资本、鑫鼎国瑞、博时创新","inv":"中金资本、鑫鼎国瑞、博时创新"},{"date":"2021-04","round":"A 轮","amount":"未披露","investors":"中信金石、天惠投资基金、安芯投资、深圳市高上资本","inv":"中信金石、天惠投资基金、安芯投资、深圳市高上资本"}],"note":"并购标的视角：株洲科能是高纯稀散金属领域的准龙头，精铟产品国内市占率 2023/2024 年第一，2025 年归母净利 1.28 亿元、扣非 1.22 亿元，利润质地扎实，远超 5000 万门槛。股权结构对并购极为友好——赵科峰、唐燕夫妇直接和间接控制 61.05% 股份，加上弟弟赵科湘（2.78%）、妹妹赵晓江（0.19%）构成一致行动关系后合计控制 64.01%，是典型的「家族绝对控股、可一次性协议转让」结构。核心障碍有两处：（1）公司正在第二次冲刺科创板 IPO（2026-05-11 受理），出售意愿取决于 IPO 进程，属于时效性窗口；（2）报告期经营活动现金流量净额连续三年为负（2023—2025 年分别为 −1.27 亿、−3.29 亿、−1.89 亿元），系囤积原材料备货所致，需重点核查存货质量与营运资金缺口；（3）实控人夫妇均持有澳大利亚永久居留权，交易架构设计需考虑外汇与跨境合规；（4）前次申报曾遭监管警示，信披历史需尽调。"}'::jsonb, now())
ON CONFLICT (name) DO UPDATE SET code=EXCLUDED.code, industry=EXCLUDED.industry, seg=EXCLUDED.seg, listed=EXCLUDED.listed, round=EXCLUDED.round, cap=EXCLUDED.cap, valuation=EXCLUDED.valuation, rev=EXCLUDED.rev, last_funding=EXCLUDED.last_funding, data=EXCLUDED.data, updated_at=now();

INSERT INTO research_companies (name, code, industry, seg, listed, round, cap, valuation, rev, last_funding, data, updated_at) VALUES
('映日科技', NULL, 'semiconductor', 'material', false, '北交所 IPO 已受理', NULL, NULL, NULL, NULL,
'{"name":"映日科技","industry":"semiconductor","seg":"material","listed":false,"round":"北交所 IPO 已受理","market":"CN","desc":"芜湖映日科技股份有限公司，2015 年 8 月由罗永春、李焕义、郑永定、魏德福、红桥节能、美泰真空、红桥新能源和携合投资等 8 名厦门映日原股东出资设立，注册地安徽芜湖。公司专业从事高性能溅射靶材的研发、生产及销售，是国内首批掌握大尺寸 ITO 靶材制造工艺的企业之一。主要产品覆盖氧化物靶材、金属靶材和其他靶材等多种尺寸和形态，已研制出 IZO、IGZO、H-ITO、高阻靶材、高迁移率氧化铟基系列、氧化锡基、银合金、钼合金、镍基合金等一系列新型靶材。2024 年公司 ITO 靶材在国内平面显示领域排名前二，其中 ITO 旋转靶排名第一。截至 2025 年 12 月 31 日，公司取得专利 100 项（发明 38 项、实用新型 62 项），先后获国家级制造业单项冠军、国家级专精特新重点「小巨人」企业、「国家知识产权优势企业」等称号，并协同制定《氧化铟锡靶材》《氧化锌铝靶材》等多项国家标准及行业标准。2023—2025 年营业收入分别为 5.22 亿元、6.46 亿元、7.73 亿元；净利润分别为 1.02 亿元、1.02 亿元、1.316 亿元，扣非后归母净利润分别为 0.97 亿元、1.07 亿元、1.225 亿元。2025 年经营活动产生的现金流量净额 1.48 亿元。公司曾于 2022 年 4 月冲击创业板 IPO，2023 年 2 月撤回；2025 年 9 月 3 日启动北交所 IPO 辅导（中信建投），2026 年 6 月 29 日 IPO 获北交所受理，拟募资 5.3 亿元。","tech":[{"date":"2026-06","title":"北交所 IPO 获受理，拟募资 5.3 亿元","kind":"融资","desc":"6 月 29 日北交所官网显示公司 IPO 获受理，保荐机构为中信建投证券。本次拟募资 5.3 亿元，用于高性能溅射靶材改扩建项目、前瞻领域高性能溅射靶材研发项目等。"},{"date":"2025-09","title":"启动北交所 IPO 辅导","kind":"融资","desc":"9 月 3 日公司启动 IPO 辅导，拟冲刺北交所，中信建投证券担任辅导机构。此前公司曾于 2022 年 4 月冲击创业板，2023 年 2 月 20 日撤回申请，原因为「自筹划以来历时较长、市场环境发生较大变化」。"},{"date":"2025","title":"大尺寸 ITO 靶材打破海外垄断，旋转靶国内第一","kind":"产品","desc":"公司掌握纳米原料粉末制备技术、纳米粉末处理技术、大尺寸素坯成型技术等核心技术，在纯度、密度、微观结构及绑定强度等关键性能指标上达到行业先进水平，是国内少数可向半导体显示面板领域知名客户同时批量供应大尺寸 ITO 旋转靶及平面靶的企业。2024 年 ITO 靶材国内平面显示领域排名前二，ITO 旋转靶排名第一。"},{"date":"2025","title":"正式进入京东方及和辉光电 AMOLED 产线供应链","kind":"市场","desc":"公司已实现对华星光电、惠科集团、群创光电、友达光电、天马微电子、超视界等企业 TFT-LCD 面板生产线批量供货，并正式进入京东方及和辉光电的 AMOLED 面板生产线供应链，成功导入国内首条 8.6 代 OLED 面板生产线。在触控模组领域与长信科技、伯恩光学深度合作；在半导体光电子与新能源领域与三安光电、华灿光电、通威太阳能、纤纳新能源合作。"},{"date":"2025","title":"净利润 1.32 亿元，经营活动现金流净额激增 91.55 倍","kind":"业绩","desc":"2025 年公司实现营业收入 7.73 亿元，净利润 1.316 亿元，毛利率 26.69%；截至 2025 年经营活动产生的现金流量净额为 1.48 亿元，较上期增加 91.55 倍。"},{"date":"2021-07","title":"前实际控制人罗永春因虚开增值税专用发票被判刑","kind":"风险","desc":"前任实际控制人罗永春因于 2013 年至 2015 年经营厦门映日期间接受供应商虚开增值税专用发票，于 2021 年 7 月 14 日被判处有期徒刑三年、缓刑三年六个月。自 2019 年 7 月起原创始团队陆续向张兵转让股份，张兵自 2022 年 1 月至今一直为公司第一大股东。罗永春目前仍持有公司 12.61% 股份，为第三大股东。"}],"executives":[{"name":"张兵","title":"董事长、控股股东、实际控制人","role":"board","shares":"直接 30.09%，通过映鑫管理控制 3.77%，合计控制 33.86% 表决权","bio":"公司现任实际控制人，2019 年加入映日科技，此前在长信科技任职。虽为实控人但并非公司创始人。自 2022 年 1 月至今一直为公司第一大股东。已与京东方、惠科等股东签署对赌协议，约定在规定日期实现上市，否则将履行回购义务。"},{"name":"罗永春","title":"第三大股东（前实际控制人）","role":"board","shares":"12.61%","bio":"公司原创始股东之一，2015 年 8 月与其他 7 名厦门映日原股东共同出资设立映日有限。因 2013—2015 年经营厦门映日期间接受供应商虚开增值税专用发票，于 2021 年 7 月 14 日被判处有期徒刑三年、缓刑三年六个月。2019 年 7 月起向张兵转让股份。"}],"investorsStructured":[{"name":"长信科技","role":"other","round":"战略持股","date":"2025","kind":"cvc","note":"通过美泰真空持股 6.57%"},{"name":"京东方","role":"other","round":"战略持股","date":"2025","kind":"cvc","note":"通过旗下芯动能管理的津显智链投资持股 4.47%"},{"name":"TCL","role":"other","round":"战略持股","date":"2025","kind":"cvc","note":"通过晟泽管理和 TCL 战投合计持股 3.57%"},{"name":"中信金石","role":"other","round":"战略持股","date":"2025","kind":"pe","note":"通过金石制造业转型升级新材料基金持股 2.91%"},{"name":"惠科","role":"other","round":"战略持股","date":"2025","kind":"cvc","note":"通过旗下广西科锰投资持股 2.58%"},{"name":"洪泰基金","role":"other","round":"战略持股","date":"2025","kind":"vc","note":"通过旗下基金龙门投资持股 1.70%"},{"name":"国元种子基金","role":"other","round":"战略持股","date":"2025","kind":"gov"}],"funding":[{"date":"2026-06","round":"北交所 IPO 受理","amount":"拟募 5.3 亿元","investors":"中信建投证券保荐（公开发行）","inv":"中信建投证券保荐（公开发行）"}],"note":"并购标的视角：映日科技的控制权结构天然适合作为易主标的——董事长张兵直接持股 30.09%、通过映鑫管理控制 3.77%，合计仅控制 33.86% 表决权，比例偏低且无绝对控股股东，属于典型的「控制权可谈」标的；同时股东名单中聚集了长信科技（6.57%）、京东方（4.47%）、TCL（3.57%）、惠科（2.58%）、中信金石（2.91%）、洪泰基金（1.70%）等产业与财务投资人，退出诉求明确，交易对手方容易撮合。基本面扎实：2025 年净利 1.316 亿元、扣非 1.225 亿元，经营活动现金流净额 1.48 亿元（同比激增 91.55 倍），是本次候选池中现金流质量最好的标的之一。核心障碍有三：（1）已与京东方、惠科等股东签署对赌协议，约定上市期限否则履行回购义务，收购前必须先解除或承继对赌；（2）前实际控制人罗永春因接受虚开增值税专用发票被判刑（2021 年，缓刑三年六个月），其仍持有 12.61% 股份为第三大股东，该股权构成历史合规瑕疵，需重点尽调并设计清理方案；（3）公司正在北交所 IPO 审核中（2026-06-29 受理），存在时效性窗口。"}'::jsonb, now())
ON CONFLICT (name) DO UPDATE SET code=EXCLUDED.code, industry=EXCLUDED.industry, seg=EXCLUDED.seg, listed=EXCLUDED.listed, round=EXCLUDED.round, cap=EXCLUDED.cap, valuation=EXCLUDED.valuation, rev=EXCLUDED.rev, last_funding=EXCLUDED.last_funding, data=EXCLUDED.data, updated_at=now();

INSERT INTO research_companies (name, code, industry, seg, listed, round, cap, valuation, rev, last_funding, data, updated_at) VALUES
('永志股份', '874701.NQ', 'semiconductor', 'material', false, '北交所 IPO 已问询', NULL, NULL, NULL, NULL,
'{"name":"永志股份","code":"874701.NQ","industry":"semiconductor","seg":"material","listed":false,"round":"北交所 IPO 已问询","market":"CN","desc":"江苏永志半导体材料股份有限公司，2002 年成立于江苏泰州，2024 年 12 月完成股份改制，在新三板挂牌（874701）。公司专业从事半导体芯片封装材料的研发、生产和销售，主要产品包括冲压引线框架、蚀刻引线框架和 MIS 封装基板，广泛应用于消费电子、工业控制、新能源及汽车等领域。公司是国家级高新技术企业、国家级专精特新「小巨人」企业，同时获评江苏省省级企业技术中心、江苏省先进级智能工厂。掌握高精度冲压技术体系、精密金属表面处理及电镀技术、蚀刻工艺等核心技术，截至公开转让说明书签署日已取得专利 128 项，其中发明专利 47 项。2023—2025 年营业收入分别为 7.75 亿元、9.81 亿元、11.72 亿元；归母净利润分别为 247.92 万元、6008.64 万元、7335.93 万元（同比 +22.09%）；扣非后归母净利润分别为 580.58 万元、6385.15 万元、7408.83 万元。2025 年毛利率 15.93%，研发投入 3517.05 万元（占营收 3.00%）。公司北交所 IPO 于 2026 年 6 月 25 日获受理，保荐机构为华泰联合证券，目前审核状态为「已问询」，2026 年 9 月 28 日已回复首轮问询。","tech":[{"date":"2026-09","title":"回复北交所首轮问询，十大问题聚焦传统封装创新与负毛利存货","kind":"公告","desc":"公司回复北交所 IPO 首轮问询，涉及传统封装技术创新、收购芯智联、收入确认与负毛利存货等核心关切。监管关注到公司部分产品（蚀刻引线框架、封装基板）收入规模较小且毛利率偏低，在此背景下募投项目的必要性与合理性受到质疑。公司回复称负毛利主要系部分新产品在量产初期良率较低、固定成本分摊较高所致，随产能爬坡与良率提升将逐步改善。"},{"date":"2026-06","title":"北交所 IPO 获受理，保荐机构华泰联合证券","kind":"融资","desc":"北交所 IPO 于 2026 年 6 月 25 日获受理，保荐机构为华泰联合证券有限责任公司，保荐代表人梁旭、陈晓峰，审计机构为北京德皓国际会计师事务所，律所为江苏世纪同仁律师事务所。募集资金拟用于半导体封装材料产能扩建、研发中心升级及补充流动资金。"},{"date":"2025","title":"营收 11.72 亿元、净利 7335.93 万元创历史新高","kind":"业绩","desc":"2025 年公司实现营业收入 11.72 亿元，同比增长 19.48%；归母净利润 7335.93 万元，同比增长 22.09%；扣非后归母净利润 7408.83 万元；加权平均净资产收益率 13.92%。毛利率 15.93%，较 2024 年 16.53% 略有下降。"},{"date":"2025","title":"MIS 封装基板与蚀刻引线框架连年低毛利","kind":"风险","desc":"公司产品集中于传统封装引线框架，先进封装技术储备薄弱；蚀刻引线框架与封装基板连续多年低毛利，部分新产品量产初期出现负毛利。监管在问询中要求公司说明募投项目必要性与合理性，公司称募投主要针对产能紧张的冲压引线框架及高功率模块类产品。"},{"date":"2025","title":"客户覆盖士兰微、长电科技、通富微电、安森美等","kind":"市场","desc":"公司已成为士兰微、长电科技、通富微电、智路封测、安森美半导体、华润微、比亚迪半导体、格力电器等国内外知名半导体厂商的重要供应商，并已进入全球封测龙头日月光的合格供应商名录。问询中监管关注通富微电与安森美等客户收入下滑是否企稳。"},{"date":"2025","title":"收购芯智联，经营现金流仅 242.65 万元","kind":"风险","desc":"报告期内公司实现收购芯智联事项，北交所问询涉及该收购的定价公允性与协同性。2025 年经营活动产生的现金流量净额仅 242.65 万元（2024 年 −562.92 万元、2023 年 −220.60 万元），低于净利润水平，现金流质量偏弱。"}],"executives":[{"name":"熊志","title":"董事长兼总经理、控股股东、实际控制人","role":"board","shares":"直接 4363.1751 万股 · 38.4992%；另一致行动人合计控制 47.5080% 表决权","bio":"男，1966 年 1 月出生，中国国籍，无境外永久居留权，初中学历。1983 年 9 月至 1985 年 9 月就职于上海八一三运输公司；1986 年 5 月至 1994 年 5 月在泰兴市商业局运输公司担任驾驶员；1993 年 5 月至今担任泰兴光电厂执行董事；2007 年 10 月至 2020 年 9 月担任有限公司执行董事兼总经理；2010 年 3 月至 2021 年 6 月担任中船永志泰兴电子科技有限公司副董事长、总经理；2006 年 4 月至今担任永强电子执行董事兼总经理；2020 年 9 月至 2024 年 12 月担任有限公司董事长兼总经理；2021 年 1 月至今担任永芯半导体执行董事；2024 年 12 月至今担任永志股份董事长兼总经理。同时担任泰兴永志、江阴永志两个员工持股平台执行事务合伙人，分别控制 3.2178%、1.9306% 股份表决权。"},{"name":"殷杰女","title":"股东（一致行动人）","role":"board","shares":"0.0838%","bio":"系熊志之配偶及一致行动人。"},{"name":"殷继平","title":"股东（一致行动人）","role":"board","shares":"3.7765%","bio":"系殷杰女之弟、熊志之妻弟，已与熊志签署《一致行动人协议》。"}],"funding":[{"date":"2026-06","round":"北交所 IPO 受理","amount":"拟募资用于半导体封装材料产能扩建等","inv":"华泰联合证券保荐（公开发行）"},{"date":"2025-08","round":"新一轮（B轮口径）","inv":"毅达资本"},{"date":"2024","round":"战略融资（加码）","inv":"毅达资本"},{"date":"2022-04","round":"战略融资","amount":"数亿元","inv":"中金传化基金领投，新洁能、无锡金投等跟投"}],"investorsStructured":[{"name":"中金传化基金","role":"lead","round":"战略融资","date":"2022-04","kind":"pe","note":"中金资本与传化控股合资"},{"name":"毅达资本","role":"lead","round":"战略融资（加码）","date":"2024","kind":"vc"},{"name":"新洁能","role":"follow","round":"战略融资","date":"2022-04","kind":"cvc"},{"name":"无锡金投","role":"follow","round":"战略融资","date":"2022-04","kind":"gov"}],"note":"并购标的视角：永志股份是功率半导体封装引线框架细分领域的国内领先者，2025 年营收 11.72 亿元、归母净利 7335.93 万元（扣非 7408.83 万元），扣非高于归母说明利润质地干净、无政府补助依赖，过 5000 万门槛较稳。股权结构清晰且集中：熊志直接持股 38.50%，加上两个员工持股平台（泰兴永志 3.22%、江阴永志 1.93%）、配偶殷杰女（0.08%）与妻弟殷继平（3.78%），合计控制 47.51% 表决权，为控股股东和实际控制人，具备协议转让控制权的操作空间。赛道契合度中等：引线框架与封装基板属半导体封装材料，但公司产品结构以传统封装为主，先进封装（如 MIS 基板升级）技术储备尚薄弱，与算力/载板方向的直接协同度弱于睿龙科技与映日科技。核心障碍：（1）公司北交所 IPO 处于「已问询」阶段，2026 年 9 月已回复首轮问询，独立性、募投必要性与负毛利存货问题被监管重点质疑，这既是收购谈判的筹码，也意味着若收购可能导致 IPO 终止的沟通成本；（2）客户集中度与部分客户收入下滑风险（通富微电、安森美）；（3）经营活动现金流长期偏弱（2025 年仅 242.65 万元），需核查营运资金真实性与应收质量。"}'::jsonb, now())
ON CONFLICT (name) DO UPDATE SET code=EXCLUDED.code, industry=EXCLUDED.industry, seg=EXCLUDED.seg, listed=EXCLUDED.listed, round=EXCLUDED.round, cap=EXCLUDED.cap, valuation=EXCLUDED.valuation, rev=EXCLUDED.rev, last_funding=EXCLUDED.last_funding, data=EXCLUDED.data, updated_at=now();

INSERT INTO research_companies (name, code, industry, seg, listed, round, cap, valuation, rev, last_funding, data, updated_at) VALUES
('信联电科', '874723.NQ', 'semiconductor', 'material', false, '北交所 IPO 已受理', NULL, NULL, NULL, NULL,
'{"name":"信联电科","code":"874723.NQ","industry":"semiconductor","seg":"material","listed":false,"round":"北交所 IPO 已受理","market":"CN","desc":"信联电子材料科技股份有限公司，2005 年 8 月 22 日成立，注册地河北省沧州临港经济技术开发区，2026 年 1 月 26 日在新三板挂牌（874723），市场分层为创新层，推荐挂牌券商及持续督导券商均为招商证券，实际控制人刘颂军。公司是一家专注于湿电子化学品领域的高新技术企业，主要从事光刻工艺核心功能材料的研发、生产及销售，主要产品为半导体显示和集成电路领域用 TMAH 显影液，以及金属剥离胶、抗反射涂层、去胶液、光刻胶等其他光刻功能材料。公司 TMAH 显影液技术指标优于国家标准 GB/T37403-2019 中最高的 I 类标准，已在 Micro-LED、OLED、AMOLED、TFT-LCD 产线中规模化应用，下游客户产品涵盖 2.5 代至高世代 10.5 代线；并已在集成电路 3D NAND 存储芯片制造及 DRAM 芯片制造中成熟应用，在国内晶圆代工厂实现量产供应。根据中国电子材料行业协会统计，2023 年公司 TMAH 显影液销量位居国内第二、全球前三。2023—2025 年营业收入分别为 3.02 亿元、3.37 亿元、4.06 亿元；净利润分别为 0.3837 亿元、0.2640 亿元、0.5286 亿元（同比 +100.24%）；扣非前后孰低净利润 2024 年、2025 年分别为 2599.90 万元、5285.77 万元；加权平均净资产收益率分别为 7.82%、14.15%。公司曾于 2023 年 7 月申报科创板辅导备案，后变更为北交所，2026 年 4 月完成变更，6 月 16 日通过河北证监局辅导验收，6 月 29 日北交所 IPO 获受理。","tech":[{"date":"2026-06","title":"北交所 IPO 获受理，募资投向荆州显影液生产基地","kind":"融资","desc":"6 月 29 日北交所官网显示公司向不特定合格投资者公开发行股票并在北交所上市的申请已获受理。本次募资拟投向湖北荆州显影液生产基地建设及补充流动资金，上市后有望进一步提升湿电子化学品领域的产能规模与市场份额。公司于 6 月 16 日通过河北证监局辅导验收。"},{"date":"2026-01","title":"新三板挂牌，进入创新层","kind":"资质","desc":"公司于 2026 年 1 月 26 日在新三板挂牌，转让方式为集合竞价，总股本 11495 万股，市场分层创新层，首次交易日 2026 年 6 月 4 日。"},{"date":"2025","title":"净利润 5285.77 万元同比增长 100.24%","kind":"业绩","desc":"报告期内公司实现营业收入 40612.45 万元，归属于挂牌公司股东净利润 5285.77 万元，同比变动 100.24%；截至报告期末公司总资产 99451.15 万元，较期初增长 21.52%。"},{"date":"2025","title":"多项产能项目落地投产，拓展光刻胶业务","kind":"产能","desc":"报告期内 6 万吨/年电子级四甲基碳酸氢铵（60%wt）扩建项目已投产；1500 吨/年光刻胶及 3000 吨/年光刻胶配套试剂项目完成部分投产；6 万吨/年电子级四甲基氢氧化铵（25%wt）扩建项目（二期）已建设完成，预计 2026 年 7 月验收投产。公司另开展超级电容业务板块，项目正在建设中。"},{"date":"2025","title":"TMAH 显影液销量国内第二、全球前三","kind":"市场","desc":"公司是半导体显示领域用 TMAH 显影液的领先企业，根据中国电子材料行业协会统计，2023 年公司 TMAH 显影液销量位居国内第二、全球前三，成为京东方、华星光电、天马微电子、惠科股份、维信诺等全球领先半导体显示企业 TMAH 显影液的主要供应商。"},{"date":"2025","title":"集成电路领域客户持续拓展中","kind":"市场","desc":"公司 TMAH 显影液已在集成电路 3D NAND 存储芯片制造及 DRAM 芯片制造中成熟应用，在国内晶圆代工厂实现量产供应。2025 年公司持续拓展集成电路领域客户，目前有多家集成电路领域客户正在产品验证中。"}],"executives":[{"name":"刘颂军","title":"法定代表人、实际控制人","role":"board","bio":"公司实际控制人，通过上海金雨投资股份有限公司持有公司 53.34% 股份，为公司控股股东。"}],"investorsStructured":[{"name":"上海金雨投资","role":"lead","round":"挂牌前持股","date":"2026","kind":"pe","note":"持股 53.34%，刘颂军控制的控股股东"},{"name":"国投京津冀科技成果转化创业投资基金","role":"follow","round":"挂牌前持股","date":"2026","kind":"gov","note":"持股 9.73%，国投系基金"},{"name":"上海特聚清","role":"follow","round":"挂牌前持股","date":"2026","kind":"pe","note":"持股 7.59%"},{"name":"上海万速祥","role":"follow","round":"挂牌前持股","date":"2026","kind":"pe","note":"持股 3.79%"},{"name":"上海兴芯","role":"follow","round":"挂牌前持股","date":"2026","kind":"pe","note":"持股 3.79%"},{"name":"上海迈乐维","role":"follow","round":"挂牌前持股","date":"2026","kind":"pe","note":"持股 3.72%"},{"name":"上海力隆财","role":"follow","round":"挂牌前持股","date":"2026","kind":"pe","note":"持股 3.67%"},{"name":"上海晟晶实业","role":"follow","round":"挂牌前持股","date":"2026","kind":"pe","note":"持股 3.61%"},{"name":"上海庚芯","role":"follow","round":"挂牌前持股","date":"2026","kind":"pe","note":"持股 2.53%"}],"funding":[{"date":"2026-06","round":"北交所 IPO 受理","amount":"募投荆州显影液生产基地及补流","investors":"招商证券持续督导（公开发行）","inv":"招商证券持续督导（公开发行）"}],"note":"并购标的视角：信联电科是湿电子化学品细分龙头，TMAH 显影液 2023 年销量国内第二、全球前三，产品已在京东方、华星光电、天马、惠科、维信诺等主流显示产线规模化应用，并进入 3D NAND 与 DRAM 制造环节，赛道属半导体材料国产替代的硬缺口品种。基本面成长性强：2025 年净利 5285.77 万元（扣非前后孰低口径）同比增长 100.24%，ROE 从 7.82% 提升至 14.15%；产能端 6 万吨电子级四甲基碳酸氢铵已投产、1500 吨光刻胶及 3000 吨配套试剂部分投产、6 万吨 TMAH 二期预计 2026 年 7 月验收投产，增量明确。股权结构对并购友好：刘颂军通过上海金雨投资持股 53.34% 为绝对控股股东，具备协议转让控制权条件；其余股东多为上海系合伙企业，股权分散。核心障碍：（1）体量偏小，2025 年营收仅 4.06 亿元，在深主板上市公司并购中属小额交易，可能触发业绩承诺与商誉压力；（2）利润刚过 5000 万门槛（5285.77 万元），安全边际薄；（3）超级电容业务为新拓展板块且仍在建设中，存在业务分散与投资风险；（4）北交所 IPO 正在审核中，存在时效性窗口。"}'::jsonb, now())
ON CONFLICT (name) DO UPDATE SET code=EXCLUDED.code, industry=EXCLUDED.industry, seg=EXCLUDED.seg, listed=EXCLUDED.listed, round=EXCLUDED.round, cap=EXCLUDED.cap, valuation=EXCLUDED.valuation, rev=EXCLUDED.rev, last_funding=EXCLUDED.last_funding, data=EXCLUDED.data, updated_at=now();

INSERT INTO research_companies (name, code, industry, seg, listed, round, cap, valuation, rev, last_funding, data, updated_at) VALUES
('算苗科技', NULL, 'semiconductor', 'design', false, 'A 轮', NULL, 120, NULL, '2026-10',
'{"name":"算苗科技","industry":"semiconductor","seg":"design","listed":false,"round":"A 轮","valuation":120,"lastFunding":"2026-10","rev":null,"cap":null,"pe":null,"desc":"算苗科技（北京）有限公司（SUNMMIO），2022 年 11 月成立于北京海淀，3D 架构 AI 云端大算力芯片设计公司，首创 3D TokenPU 架构。核心产品为面向大模型推理的 3D TokenPU 系列芯片，第一代 A4E 于 2026 年 6 月 15 日正式流片——基于自研 RISC-V 架构，采用 3D 混合键合（Hybrid Bonding）将 8 层存储晶圆垂直堆叠于计算逻辑晶圆之上，通过 TSV + 微凸点实现微米级互联，达成 16TB/s 超大访存带宽；第二代 A4S 定义已完成，计划 2027 年 Q1 流片，A4E 同期进入规模量产。技术上主打 Tile-Native 软硬件协同（以 Tile 为数据搬运、存储与计算的基本单元，「一次搬运、多次复用」），硬件侧具备原生 Tile 级调度与多精度动态切换能力，软件侧适配 LLVM、Triton 编译工具栈；采用国产较成熟制程，已构建覆盖芯片设计、核心 IP、制造、封装的国产化供应链体系。团队核心成员具备近 7 年行业深耕与上万片 3D IC 晶圆量产经验，2019 年底即锁定混合键合 3D 堆叠架构，2021 年做出全球第一颗量产交付的 3D 堆叠算力芯片。截至 2026 年 10 月，一年内累计融资近 20 亿元，最新估值 120 亿元。","latestTech":"第一代 3D TokenPU 芯片 A4E 于 2026 年 6 月 15 日流片，8 层存储晶圆 3D 混合键合堆叠实现 16TB/s 访存带宽；A4S 计划 2027 年 Q1 流片并进入规模量产","tech":[{"date":"2026-10","title":"宣布完成 Pre-A2 轮及 A 轮融资，由亦庄国投等北京市区两级国资平台领投，本轮总额超 10 亿元，一年内累计融资近 20 亿元","kind":"融资"},{"date":"2026-06","title":"第一代 3D TokenPU 芯片 A4E 正式流片：自研 RISC-V 架构 + 3D 混合键合 8 层存储晶圆垂直堆叠，TSV/bump 微米级互联，实现 16TB/s 超大访存带宽","kind":"产品"},{"date":"2026-06","title":"第二代 3D TokenPU 芯片 A4S 定义完成，计划 2027 年 Q1（2 月）流片，与 A4E 规模量产同期推进，目标性能倍增（架构优化后可达 2-3 倍）","kind":"产品"},{"date":"2026","title":"提出 Tile-Native 软硬件协同架构，以 Tile 为数据搬运、存储与计算的基本单元实现「一次搬运、多次复用」，硬件原生支持 Tile 级调度与多精度动态切换，软件适配 LLVM、Triton 编译工具栈","kind":"技术"},{"date":"2025-12","title":"完成首轮超 4 亿元融资，源码资本、石溪资本领投","kind":"融资"},{"date":"2021","title":"团队完成全球第一颗量产交付的 3D 堆叠算力芯片，核心成员累计具备上万片 3D IC 晶圆量产经验","kind":"技术"}],"execChanges":[{"date":"2026-09-11","event":"工商主要成员变更：戴旭光退出，吕毅新增为董事"}],"executives":[{"name":"汪福全","title":"创始人、董事长兼 CEO","role":"board","bio":"中国科学院声学研究所国家重点实验室博士、研究员，师从水声物理学家张仁和院士，主攻高通量阵列信号处理；后于中国科学院计算技术研究所从事计算机体系结构博士后研究，合作导师为龙芯首席科学家胡伟武。2009 年创办中科声龙，曾带领团队研发出全球首款存算一体高通量算力芯片。2022 年 11 月创立算苗科技，任董事长兼经理，是公司大股东。"},{"name":"刘明","title":"联合创始人兼 CTO","role":"management","bio":"中国科学院计算技术研究所博士，师从龙芯首席科学家胡伟武，在龙芯半导体从事处理器研发 15 年，具备两次 3D 堆叠芯片研发成功经验，在算苗科技负责芯片架构与产品定义。"},{"name":"楼建光","title":"首席人工智能科学家","role":"management","tenure":"2025.9 至今","bio":"中国科学院自动化研究所博士，师从计算机视觉与模式识别专家谭铁牛院士，拥有 20 年机器学习、自然语言处理与人工智能研究经验，曾任微软研究院首席研究员。2025 年 9 月加入算苗科技，为创始人汪福全在浙江大学的师弟。"},{"name":"闫超","title":"首席算法科学家","role":"management","bio":"中国科学院声学研究所博士（汪福全学生），具备 12 年龙芯处理器研发经验与 15 年算法与系统研究经验，在算苗科技负责推理算法与系统软件方向。"},{"name":"张洵","title":"董事","role":"board"},{"name":"吕毅","title":"董事","role":"board","tenure":"2026.9 至今"},{"name":"查正亮","title":"董事","role":"board"},{"name":"牛晶晶","title":"监事","role":"board"},{"name":"刘丽丽","title":"财务负责人","role":"management"}],"investorsStructured":[{"name":"亦庄国投","role":"lead","round":"A 轮","date":"2026-10","kind":"gov","note":"北京市区两级国资平台领投"},{"name":"国开金融","role":"follow","round":"A 轮","date":"2026-10","kind":"gov","note":"国家开发银行旗下国家级产业投资基金"},{"name":"北工投资","role":"follow","round":"Pre-A+ 轮","date":"2026-09","kind":"gov","note":"北京工业发展投资管理有限公司"},{"name":"北京顺禧基金","role":"follow","round":"Pre-A+ 轮","date":"2026-09","kind":"gov"},{"name":"中关村科学城科技投资","role":"follow","round":"Pre-A+ 轮","date":"2026-09","kind":"gov"},{"name":"北京市人工智能产业投资基金","role":"follow","round":"Pre-A+ 轮","date":"2026-09","kind":"gov"},{"name":"北京京国盛投资基金","role":"follow","round":"Pre-A+ 轮","date":"2026-09","kind":"gov"},{"name":"北京中关村科学城四期","role":"follow","round":"Pre-A+ 轮","date":"2026-09","kind":"gov"},{"name":"源码资本","role":"lead","round":"首轮","date":"2025-12","kind":"vc","note":"联合领投，超 4 亿元首轮融资"},{"name":"石溪资本","role":"lead","round":"首轮","date":"2025-12","kind":"vc","note":"联合领投，超 4 亿元首轮融资"},{"name":"襄禾资本","role":"follow","round":"Pre-A 轮","date":"2026","kind":"vc"},{"name":"嘉御资本","role":"follow","round":"Pre-A+ 轮","date":"2026-09","kind":"vc"},{"name":"沃赋创投","role":"follow","round":"Pre-A+ 轮","date":"2026-09","kind":"vc"},{"name":"千乘资本","role":"follow","round":"Pre-A+ 轮","date":"2026-09","kind":"vc"},{"name":"德道厚生投资","role":"follow","round":"Pre-A+ 轮","date":"2026-09","kind":"vc"},{"name":"超越创投","role":"follow","round":"Pre-A+ 轮","date":"2026-09","kind":"vc"},{"name":"誉尊基金","role":"follow","round":"Pre-A+ 轮","date":"2026-09","kind":"vc"},{"name":"北京若森","role":"follow","round":"Pre-A+ 轮","date":"2026-09","kind":"vc"},{"name":"宁波庆芯","role":"follow","round":"Pre-A+ 轮","date":"2026-09","kind":"vc"},{"name":"联想创投","role":"strategic","round":"Pre-A 轮","date":"2026","kind":"cvc","note":"联想集团产业资本"},{"name":"智微基金","role":"follow","round":"Pre-A+ 轮","date":"2026-09","kind":"cvc","note":"上海智微攀峰系主体"}],"funding":[{"date":"2026-10","round":"A 轮","amount":"超 10 亿元（Pre-A2 轮 + A 轮合计）","inv":"领投：亦庄国投等北京市区两级国资平台；参与：国开金融等","investors":"亦庄国投（领投）· 北京市区两级国资平台 · 国开金融"},{"date":"2026-09","round":"Pre-A+ 轮","amount":"未披露（累计近 10 亿元）","inv":"北工投资 / 沃赋创投 / 千乘资本 / 中关村科学城科技投资 / 德道厚生投资 / 嘉御资本 / 智微基金 / 超越创投 / 顺禧基金 / 誉尊基金 / 北京若森","investors":"北工投资 · 沃赋创投 · 千乘资本 · 中关村科学城科技投资 · 德道厚生投资 · 嘉御资本 · 智微基金 · 超越创投 · 顺禧基金 · 誉尊基金 · 北京若森"},{"date":"2026","round":"Pre-A 轮","amount":"未披露（Pre-A 与 Pre-A+ 累计近 10 亿元）","inv":"源码资本 / 襄禾资本 / 联想创投等","investors":"源码资本 · 襄禾资本 · 联想创投"},{"date":"2025-12","round":"首轮（天使/种子）","amount":"超 4 亿元","inv":"领投：源码资本 / 石溪资本","investors":"源码资本（领投）· 石溪资本（领投）"}],"note":"3D 堆叠 AI 大算力芯片国产替代对标：算苗科技以 3D 混合键合（Hybrid Bonding）将存储晶圆垂直堆叠于计算逻辑晶圆，用 16TB/s 访存带宽直击大模型推理的「存储墙」，技术上对标 d-Matrix（美国，数字存内计算 + 3D 近存，主打数据中心推理）、Cerebras Systems（美国，晶圆级引擎）、Groq（美国，SRAM 确定性推理）等以「绕开 HBM 瓶颈」为核心思路的推理芯片公司。与国内同赛道相比，算苗的差异化有三点：一是路线选择更激进——直接用 3D 混合键合做 8 层存储晶圆堆叠，而非传统 2.5D 封装 + HBM；二是团队具备真实的 3D IC 量产履历（核心成员上万片 3D IC 晶圆量产经验、2021 年全球首颗量产交付的 3D 堆叠算力芯片）；三是供应链全部选用国产较成熟制程，规避先进制程受限问题。风险在于：① 3D 混合键合的良率与散热是量产最大不确定性，8 层堆叠的堆叠良率乘数效应显著；② Tile-Native 架构需重建软件生态，LLVM/Triton 适配深度决定客户迁移成本；③ 公司尚未产生规模化营收，估值 120 亿元对应融资进度而言偏高，需 A4E 量产与客户导入验证；④ 2026 年 10 月刚完成 A 轮，距离申报 IPO 仍有距离。"}'::jsonb, now())
