INSERT INTO research_companies (name, code, industry, seg, listed, round, cap, valuation, rev, last_funding, data, updated_at) VALUES
('羲禾科技', NULL, 'semiconductor', 'design', false, '科创板 IPO 已过会', NULL, 37, 4.61, '2025-12',
'{"name":"羲禾科技","industry":"semiconductor","seg":"design","listed":false,"round":"科创板 IPO 已过会","valuation":37,"lastFunding":"2025-12","rev":4.61,"revGrowth":549.63,"gross":62.82,"rd":13.6,"cap":null,"pe":null,"spark":[0.06,0.71,4.61,5.69],"market":"CN","desc":"上海羲禾科技股份有限公司（Xphor Co., Ltd.），2021 年 5 月成立于上海普陀，专注于硅光集成技术的研发与商业化，主要产品为高性能硅光集成芯片，速率覆盖 400G、800G 及 1.6T，并已拓展 3.2T/6.4T 的 NPO/CPO 收发一体芯片，同时向跨数据中心互连与硅光传感（FMCW 激光雷达）延伸。采用 Fabless 模式（晶圆代工与后道封测全委外），基于 CMOS 工艺做硅光集成芯片设计与测试。据弗若斯特沙利文，2025 年公司硅光集成芯片全球市占率约 13%（收入口径）、出货量口径约 15%，均列全球第二；在独立第三方硅光集成芯片设计厂商中位居全球第一。截至 2026 年 8 月累计出货量突破 1200 万颗，产品已进入国际主要光模块厂商供应链，最终应用于国内外主要云服务厂商的 AI 集群及超大型数据中心。2025 年营收 4.61 亿元（+549.63%）并扭亏为盈（归母净利 1.76 亿元），2026 上半年营收 5.69 亿元已超 2025 全年、归母净利 1.61 亿元，2023—2025 年营收复合增长率 760.34%；截至 2026-08-31 在手订单约 45.51 亿元。2026 年 6 月 30 日科创板 IPO 获受理，2026 年 10 月 14 日通过上市委审议（受理至上会仅 106 天），拟募资 18.3 亿元。","latestTech":"2026 上半年 1.6T 硅光集成芯片进入批量交付（收入 1.03 亿元、占比 18.04%），NPO/CPO 收发一体芯片实现首批销售，800G 及 1.6T 收入合计占比升至 34.17%","tech":[{"date":"2026-10","title":"科创板 IPO 通过上交所上市委审议（2026 年第 52 次会议），受理至上会仅 106 天，保荐机构国泰海通，拟募资 18.3 亿元","kind":"融资"},{"date":"2026-09","title":"上会前夕更新招股书，取消原 6 亿元「补充流动资金」募投项目，募资总额由 24.3 亿元调减至 18.3 亿元","kind":"融资"},{"date":"2026-06","title":"NPO/CPO 收发一体芯片实现首批销售，成为云服务厂商 B 唯一中标的 NPO/CPO 硅光集成芯片合作厂商；3.2T(16×200G)/6.4T(32×200G) 收发一体芯片进入终端验证阶段","kind":"产品"},{"date":"2026-H1","title":"1.6T 硅光集成芯片进入批量交付期，上半年收入 1.03 亿元、占比 18.04%；800G 收入 9179.31 万元、占比 16.13%，高速率产品合计占比升至 34.17%","kind":"产品"},{"date":"2026","title":"突破硅光三大行业难题：渐变型倒锥形光波导将耦合损耗从行业平均 1.5dB 降至 0.5dB 并突破实心光口设计；研制低功耗单波 200Gbps 调制器用于 1.6T 芯片量产；片上复用/解复用器达到 1dB 带宽大于 18nm 的行业领先水平","kind":"技术"},{"date":"2025-12","title":"与腾讯科技（深圳）、腾讯云计算（北京）、海信宽带、上海曼光联合申报的「高性能光集成与光电协同封装技术及产业化」项目获 2025 年度上海市科技进步一等奖，公司为首家完成单位","kind":"技术"},{"date":"2025-12","title":"完成 C 轮融资 3.51 亿元，投后估值 37 亿元","kind":"融资"},{"date":"2025","title":"400G 硅光集成芯片规模量产，产品矩阵拓展至 1.6T 并支持硅光模块规模商用；当年营收 4.61 亿元（+549.63%），扭亏为盈","kind":"产品"},{"date":"2024","title":"搭建完成供应链与运营管理体系，100G/lane DR4 发射芯片实现大规模出货，100G/lane DR8、100G/lane 2×FR4 及 200G/lane DR4 发射芯片实现销售","kind":"产品"},{"date":"2023","title":"100G/lane DR4 发射芯片在插损、调制带宽与调制效率等关键性能指标上实现突破，成为国内少数掌握硅光集成芯片全链条设计能力的团队","kind":"技术"}],"execChanges":[{"date":"2025-11-26","event":"羲禾有限完成股份制改革，整体变更为上海羲禾科技股份有限公司"}],"executives":[{"name":"武爱民","title":"创始人、董事长兼总经理","role":"board","shares":"通过上海羲景等五平台合计控制 45.3944% 表决权","bio":"1980 年生，中国科学院上海微系统与信息技术研究所微电子学与固体电子学博士。2008 年至 2026 年 1 月历任中科院上海微系统所助理研究员、副研究员、研究员，2013—2014 年兼任加州大学伯克利分校访问学者。主导研发的硅基片上光源、大规模硅光集成等技术成果获上海市自然科学一等奖，个人获评上海市优秀学术带头人、国家级创新人才，在硅光集成领域拥有国家发明专利 60 余项。2021 年 5 月创办羲禾有限，历任执行董事，现任公司董事长、总经理，为实际控制人；同时持有控股股东上海羲景 34.68% 出资份额。"},{"name":"冯大增","title":"董事、副总经理兼首席技术官","role":"board","shares":"持有上海羲景 26.83% 出资份额","bio":"博士。曾任职于全球最早从事硅光开发的企业之一 Kotura（2013 年被 Mellanox 收购），2006 年即主导研发并量产全球首款基于硅光集成技术的商用可变光衰减器（VOA）芯片——该产品是当时市场上唯一能实现高性能可调光衰减功能的硅光产品，广泛应用于电信网络与数据中心。此后任 Mellanox 高级总监、副总裁（Mellanox 于 2020 年被 NVIDIA 收购）。创始团队成员，为公司核心技术人员，共同承担对赌义务。"},{"name":"王奕琼","title":"首席运营官","role":"management","shares":"持有上海羲景 22.16% 出资份额","bio":"博士。曾在早期国际领先的硅光企业 Kotura、Mellanox 任职，主导硅光工艺方向。创始团队成员、公司核心技术人员，共同承担对赌义务；曾担任公司董事，后辞任。"},{"name":"梁虹","title":"总工程师","role":"management","shares":"持有上海羲景 16.33% 出资份额","bio":"曾在早期国际领先的硅光企业 Kotura、Mellanox 任职，主导硅光封测方向。创始团队成员、公司核心技术人员，共同承担对赌义务；曾担任公司董事，后辞任。"},{"name":"吴蒙","title":"董事会秘书兼投资者关系负责人","role":"management","shares":"通过上海晗玚间接持股（上海晗玚持有上海晗矽 67.34% 出资份额）","bio":"负责公司信息披露与投资者关系工作。同时为申报前 12 个月内新增股东平台上海晗玚的合伙人（出资份额 1%，武爱民持 99%）。"}],"investorsStructured":[{"name":"上海羲景管理咨询合伙企业","role":"lead","round":"发起设立","date":"2021-05","kind":"other","note":"控股股东，持股 34.1662%，为创始团队持股平台（武爱民 34.68% / 冯大增 26.83% / 王奕琼 22.16% / 梁虹 16.33%）"},{"name":"上海晗睿管理咨询合伙企业","role":"other","round":"发起设立","date":"2021-05","kind":"other","note":"创始团队持股平台，武爱民控制 6.0118% 表决权"},{"name":"元禾原点","role":"lead","round":"天使轮","date":"2021-09","kind":"vc","note":"公司成立仅四个月即投资"},{"name":"元禾控股","role":"follow","round":"天使轮","date":"2021-09","kind":"gov","note":"苏州元禾控股，国资背景"},{"name":"舜宇投资","role":"follow","round":"天使轮","date":"2021-09","kind":"cvc","note":"舜宇光学科技旗下产业基金"},{"name":"朗玛峰创投","role":"lead","round":"Pre-A 轮","date":"2022-09","kind":"vc"},{"name":"普华资本","role":"follow","round":"Pre-A 轮","date":"2022-09","kind":"vc"},{"name":"广州科学城创投","role":"follow","round":"Pre-A 轮","date":"2022-09","kind":"gov","note":"广州开发区国资创投平台"},{"name":"南京交控","role":"follow","round":"B 轮","date":"2023-05","kind":"gov","note":"南京交通集团旗下，认购 3000 万元"},{"name":"南京金体","role":"follow","round":"B 轮","date":"2023-05","kind":"other","note":"认购 3000 万元"},{"name":"光电基金","role":"follow","round":"B 轮","date":"2024-05","kind":"gov","note":"与麟毅创投叁号、麟毅伍号合计认购 4900 万元"},{"name":"麟毅资本","role":"follow","round":"B 轮","date":"2024-05","kind":"vc","note":"麟毅创投叁号、麟毅伍号、麟毅瑞瑜、麟毅陆号、麟毅珂璟等多主体参与 B 轮"},{"name":"达晨财智","role":"follow","round":"B 轮","date":"2024-09","kind":"vc","note":"深圳达晨、杭州达晨合计参与，与朗玛八十六号、朗玛八十七号、观新光源合计认购 1.26 亿元"},{"name":"观新光源","role":"follow","round":"B 轮","date":"2024-09","kind":"other"},{"name":"中芯聚源","role":"lead","round":"B 轮","date":"2025-08","kind":"cvc","note":"中芯国际旗下产业投资平台，与金浦创新、金浦金科、聚合鹏飞二期、元禾原点四号合计认购 1.1 亿元"},{"name":"金浦投资","role":"follow","round":"B 轮","date":"2025-08","kind":"pe","note":"金浦创新、金浦金科、金浦集团多主体参与"},{"name":"聚合资本","role":"follow","round":"B 轮","date":"2025-08","kind":"vc","note":"聚合鹏飞二期"},{"name":"红杉中国","role":"lead","round":"C 轮","date":"2025-12","kind":"vc","note":"C 轮增资 3.51 亿元、投后估值 37 亿元"},{"name":"金雨茂物","role":"follow","round":"C 轮","date":"2025-12","kind":"vc"},{"name":"新鼎投资","role":"follow","round":"C 轮","date":"2025-12","kind":"vc","note":"新鼎盛捌、新鼎荣盛"},{"name":"张江高科","role":"follow","round":"C 轮","date":"2025-12","kind":"gov","note":"上海张江高科技园区开发股份有限公司（600895.SH）旗下科创基金"},{"name":"博华资本","role":"follow","round":"C 轮","date":"2025-12","kind":"pe","note":"博华投资"},{"name":"北京电控","role":"follow","round":"C 轮","date":"2025-12","kind":"gov","note":"北京电子控股旗下产业投资，与芯动能共同参与"},{"name":"芯动能","role":"follow","round":"C 轮","date":"2025-12","kind":"cvc","note":"芯动能光通、芯动能华景，半导体显示与集成电路产业资本"},{"name":"普华辰纬","role":"follow","round":"C 轮","date":"2025-12","kind":"vc"},{"name":"元禾原点四号","role":"follow","round":"C 轮","date":"2025-12","kind":"vc","note":"老股东元禾原点继续加注"},{"name":"国泰海通","role":"other","round":"IPO 保荐","date":"2026-06","kind":"other","note":"保荐机构，其关联方合计间接持股比例小于 1%"}],"funding":[{"date":"2025-12","round":"C 轮","amount":"3.51 亿元（投后估值 37 亿元）","inv":"红杉中国 / 达晨财智 / 新鼎投资 / 金浦投资 / 中芯聚源 / 张江高科 / 元禾原点 / 朗玛峰创投 / 观新光源 / 聚合鹏飞二期 / 麟毅资本 / 普华辰纬 / 舜宇投资 / 芯动能 / 博华资本 / 北京电控 等 30 家主体","investors":"红杉中国 · 达晨财智 · 新鼎投资 · 金浦投资 · 中芯聚源 · 张江高科 · 元禾原点 · 朗玛峰创投 · 观新光源 · 聚合鹏飞二期 · 麟毅资本 · 普华辰纬 · 舜宇投资 · 芯动能 · 博华资本 · 北京电控"},{"date":"2025-08","round":"B 轮","amount":"1.1 亿元","inv":"中芯聚源 / 金浦创新 / 金浦金科 / 聚合鹏飞二期 / 元禾原点四号","investors":"中芯聚源 · 金浦创新 · 金浦金科 · 聚合鹏飞二期 · 元禾原点四号"},{"date":"2024-09","round":"B 轮","amount":"1.26 亿元","inv":"朗玛八十六号 / 朗玛八十七号 / 深圳达晨 / 杭州达晨 / 观新光源","investors":"朗玛峰创投（朗玛八十六号、八十七号）· 达晨财智（深圳达晨、杭州达晨）· 观新光源"},{"date":"2024-05","round":"B 轮","amount":"4900 万元","inv":"光电基金 / 麟毅创投叁号 / 麟毅伍号","investors":"光电基金 · 麟毅创投叁号 · 麟毅伍号"},{"date":"2023-05","round":"B 轮（首批）","amount":"3000 万元","inv":"南京交控 / 南京金体","investors":"南京交控 · 南京金体"},{"date":"2022-09","round":"Pre-A 轮","amount":"未披露","inv":"朗玛峰创投 / 广州科学城创投 / 普华资本","investors":"朗玛峰创投 · 广州科学城创投 · 普华资本"},{"date":"2021-09","round":"天使轮","amount":"未披露","inv":"元禾原点 / 元禾控股 / 舜宇光学旗下产业基金","investors":"元禾原点 · 元禾控股 · 舜宇光学旗下产业基金"}],"note":"硅光集成芯片国产替代对标：羲禾科技是全球最主要的独立第三方硅光集成芯片设计公司，2025 年全球市占率约 13%（收入口径）位列第二，仅次于中际旭创（约 29%）。国际对标为 Intel（综合平台厂商，硅光业务服务自身生态并对外供货）、Cisco（偏电信）、Marvell（收购 Inphi 布局硅光 DSP 与光互连）、Broadcom（CPO 交换机平台）等。公司核心差异化在于「中立开放的独立第三方」定位——中际旭创、新易盛等光模块龙头自研硅光芯片主要配套自有模块、不对外销售，公司则可面向全市场开放供货，使下游客户无需绑定特定供应商的自研生态，在光模块行业格局分散、头部厂商竞相构建供应链自主能力的背景下，构成保障供应链弹性与技术多样性的关键一环。技术壁垒体现在「全链条」能力：同时打通超低损耗耦合、低功耗高速调制、片上波分复用等七大核心技术并实现规模化交付的厂商全球屈指可数，团队源自 Kotura / Mellanox（英伟达），2006 年即量产全球首款商用硅光 VOA 芯片。风险集中于四方面：① 客户集中度极高（前五大客户收入占比 100%→92.26%，第一大客户占比 90.90%→55.55% 且频繁变动），上交所两轮问询均重点追问业绩可持续性；② 供应商集中，第一大供应商采购占比 54.54%→90.08%，上游晶圆流片资源稀缺；③ 利润未转化为现金，2025 年与 2026 上半年经营性现金流净额仅 269.71 万元、−1375.21 万元，应收账款从 2024 年末 0.66 亿元升至 2026 上半年末 2.99 亿元，存货余额升至 1.46 亿元；④ 产品结构单一（2026 上半年 99.97% 收入来自硅光集成芯片），且龙头光模块厂商（中际旭创 1.6T 硅光良率已达 95%、800G/1.6T 中硅光方案占比超 50%）若大规模自研并改变外采策略，将直接冲击需求。此外创始团队四人共同承担对赌义务但未认定一致行动关系，被上交所问询，控制权认定与股权清晰度需持续关注。"}'::jsonb, now())
